questionvariables.text:
/*coordinates of the fixed line AB*/
x_A:rand_with_step(-5,5,1);
y_A:rand_with_step(-5,5,1);
x_B:rand_with_prohib(-5,5,[x_A]);
y_B:rand_with_prohib(-5,5,[y_A]);
/*Gradient of line AB, teachers answer*/
m_AB:(y_B-y_A)/(x_B-x_A);
eqn_AB:y=m_AB*x-m_AB*x_A+y_A;
ta:m_AB*x-m_AB*x_A+y_A;

feedbackvariables.text:
/*Mistake 1: Checks if the gradient has been calculated incorrectly e.g. m_AB:(x_B-x_A)/(y_B-y_A);  */
m_incorrect:1/m_AB;
eqn_incorrect:m_incorrect*x-m_incorrect*x_A+y_A;
mistake_1:eqn_incorrect;
